// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Aceita os dados recebidos pelo webhook
const entrada = $input.first().json;

const clientes = entrada.body?.clientes ?? entrada.clientes ?? [];
const investimentos = entrada.investimentos ?? [];

// Converte valores como "R$ 12.500,00" para 12500
function converterParaNumero(valor) {
  if (typeof valor === "number") return valor;

  const numero = String(valor ?? "")
    .replace(/[^\d,.-]/g, "")
    .replace(/\./g, "")
    .replace(",", ".");

  return Number(numero) || 0;
}

// Formata valores no padrão brasileiro
function formatarMoeda(valor) {
  return Number(valor).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

// Remove espaços extras e compara textos sem diferenciar maiúsculas
function normalizarTexto(valor) {
  return String(valor ?? "").trim().toLowerCase();
}

const resultados = clientes.map((cliente) => {
  const saldoNum = converterParaNumero(cliente.saldo);
  const perfilCliente = normalizarTexto(cliente.perfil);

  // Busca investimentos compatíveis com o perfil e com o saldo do cliente
  const compativeis = investimentos.filter((investimento) => {
    const perfilInvestimento = normalizarTexto(investimento.perfil);
    const minimo = converterParaNumero(investimento.minimo);

    const perfilCompativel =
      !perfilInvestimento || perfilInvestimento === perfilCliente;

    return perfilCompativel && saldoNum >= minimo;
  });

  // Se houver opções compatíveis, escolhe a primeira
  const escolhido = compativeis[0] ?? null;

  const mensagens = escolhido
    ? [
        `Olá, ${cliente.nome}! Pelo seu perfil (${cliente.perfil}), uma boa opção é o ${escolhido.produto} (mínimo ${formatarMoeda(converterParaNumero(escolhido.minimo))}). Com seu saldo atual de ${formatarMoeda(saldoNum)}, você já consegue investir. Rentabilidade: ${escolhido.rentabilidade}.`,
        `Oi, ${cliente.nome}! Recomendação para perfil ${cliente.perfil}: ${escolhido.produto}. Seu saldo de ${formatarMoeda(saldoNum)} atende ao valor mínimo de ${formatarMoeda(converterParaNumero(escolhido.minimo))}. Rentabilidade: ${escolhido.rentabilidade}.`,
        `${cliente.nome}, considerando seu perfil ${cliente.perfil}, o ${escolhido.produto} pode ser uma opção. Você tem ${formatarMoeda(saldoNum)} disponíveis e o investimento exige no mínimo ${formatarMoeda(converterParaNumero(escolhido.minimo))}. Rentabilidade: ${escolhido.rentabilidade}.`,
      ]
    : [
        `Olá, ${cliente.nome}! No momento, não encontramos um investimento compatível com seu perfil e saldo atual de ${formatarMoeda(saldoNum)}.`,
      ];

  // Escolhe uma mensagem aleatoriamente
  const mensagemEscolhida =
    mensagens[Math.floor(Math.random() * mensagens.length)];

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: formatarMoeda(saldoNum),
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo: escolhido ? "saldo_ok" : "sem_opcao_compativel",
    mensagens,
    mensagem_escolhida: mensagemEscolhida,
  };
});

return [
  {
    json: {
      ok: true,
      total_clientes: resultados.length,
      total_investimentos: investimentos.length,
      resultados,
    },
  },
];

const resultados = $json.resultados || [];

function parseBR(valor) {
  if (!valor) return 0;

  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();

  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// Retorna um item por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBR(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: c.email,
      nome: c.nome,
      perfil: c.perfil,
      saldo_texto: c.saldo_texto,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagens: c.mensagens,
      mensagem_escolhida: c.mensagem_escolhida
    }
  };
});

return out;

