const items = $input.all();

function extrairTexto(item) {
  // Caminho mostrado no seu input da OpenAI
  const texto = item.json.output?.[0]?.content?.find(c => c.type === "output_text")?.text;

  if (texto) return texto;

  // Alternativas para outros formatos de saída
  return item.json.text
    ?? item.json.message
    ?? item.json.content?.[0]?.text
    ?? "";
}

function converterParaObjeto(texto) {
  if (typeof texto !== "string") return texto ?? {};

  // Remove cercas Markdown, caso a IA retorne ```json ... ```
  const limpo = texto
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {
    return JSON.parse(limpo);
  } catch {
    // Tenta localizar um objeto JSON dentro do texto
    const inicio = limpo.indexOf("{");
    const fim = limpo.lastIndexOf("}");

    if (inicio !== -1 && fim > inicio) {
      try {
        return JSON.parse(limpo.slice(inicio, fim + 1));
      } catch {}
    }

    // Se não for JSON válido, mantém o texto como corpo simples
    return {
      subject: "Mensagem sobre sua recomendação de investimento",
      text_body: limpo,
      html_body: `<p>${limpo.replace(/\n/g, "<br>")}</p>`,
    };
  }
}

return items.map((item) => {
  const textoOpenAI = extrairTexto(item);
  const dados = converterParaObjeto(textoOpenAI);

  return {
    json: {
      ok: true,
      to: item.json.email_to ?? item.json.to ?? "",
      subject: dados.subject ?? "",
      text_body: dados.text_body ?? "",
      html_body: dados.html_body ?? "",
      meta: {
        nome: item.json.nome ?? "",
        perfil: item.json.perfil ?? "",
        produto: item.json.recomendacao?.produto ?? "",
        motivo: item.json.motivo ?? "",
      },
    },
  };
});
